/**
 * @brief post a message to the message queue
 *
 * @param[in] queue the handle of the queue
 * @param[in] data the data of the message
 * @param[in] timeout timeout time
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_queue_post(const TKL_QUEUE_HANDLE queue, void *data, uint32_t timeout)
{
    // --- BEGIN: user implements ---
    if (!queue || !data) {
        return OPRT_INVALID_PARM;
    }

    tkl_queue_ctx_t *ctx = (tkl_queue_ctx_t *)queue;
    BaseType_t ret;

    // Check if we are in an ISR (Interrupt)
    if (HwiP_inISR()) {
        BaseType_t xHigherPriorityTaskWoken = pdFALSE;
        
        // ISRs cannot block, so timeout is ignored (effectively 0)
        ret = xQueueSendFromISR(ctx->handle, data, &xHigherPriorityTaskWoken);
        
        // Force context switch if needed
        portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
    } 
    else {
        // Normal Thread Context
        TickType_t ticks;
        if (timeout == TKL_WAIT_FOREVER) {
            ticks = portMAX_DELAY;
        } else {
            ticks = pdMS_TO_TICKS(timeout);
        }

        ret = xQueueSend(ctx->handle, data, ticks);
    }

    if (ret != pdPASS) {
        return OPRT_OS_ADAPTER_QUEUE_SEND_FAIL;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief fetch message from the message queue
 *
 * @param[in] queue the message queue handle
 * @param[inout] msg the message fetch form the message queue
 * @param[in] timeout timeout time
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_queue_fetch(const TKL_QUEUE_HANDLE queue, void *msg, uint32_t timeout)
{
    // --- BEGIN: user implements ---
    if (!queue) {
        return OPRT_INVALID_PARM;
    }

    tkl_queue_ctx_t *ctx = (tkl_queue_ctx_t *)queue;
    uint8_t stack_buffer[32];
    void *temp_buffer = NULL;
    void *p_dest = msg;

    if (p_dest == NULL) {
        if (ctx->item_size <= sizeof(stack_buffer)) {
            p_dest = stack_buffer;
        } else {
            temp_buffer = pvPortMalloc(ctx->item_size);
            if (temp_buffer == NULL) {
                return OPRT_MALLOC_FAILED;
            }
            p_dest = temp_buffer;
        }
    }

    BaseType_t ret;

    // TODO: we wanted to assume thread context, cause timeout is illegal for interrupt, but we can't control if this function
    // will be called from inside an interrupt or not. We chose the safer way. Removing the first 'if' and assumng thread context will be faster.
    // OPTION 1: Interrupt Context
    if (HwiP_inISR()) {
        BaseType_t xHigherPriorityTaskWoken = pdFALSE;
        
        // ISRs CANNOT WAIT. Timeout is ignored (treated as 0).
        ret = xQueueReceiveFromISR(ctx->handle, p_dest, &xHigherPriorityTaskWoken);
        
        // If we successfully grabbed an item and it woke up a high-priority task
        portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
    } 
    // OPTION 2: Thread Context
    else {
        TickType_t ticks;
        if (timeout == TKL_WAIT_FOREVER) {
            ticks = portMAX_DELAY;
        } else {
            ticks = pdMS_TO_TICKS(timeout);
        }

        ret = xQueueReceive(ctx->handle, p_dest, ticks);
    }

    if (temp_buffer != NULL) {
        vPortFree(temp_buffer);
    }

    if (ret != pdPASS) {
        return OPRT_OS_ADAPTER_QUEUE_RECV_FAIL;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

